<template>
	<view v-if="visible" class="update-overlay" @tap="handleOverlayTap" @touchmove.stop.prevent>
		<view class="update-dialog" @tap.stop>
			<view class="update-header">
				<view class="app-mark"><view class="mark-dot"></view><view class="mark-panel"><view></view><view></view><view></view><view></view></view></view>
				<text class="update-kicker">版本更新</text><text class="update-title">应用有新版本了</text><text class="update-subtitle">当前 {{ currentVersion }} · 最新 {{ targetVersion }}</text>
			</view>
			<view class="update-body">
				<view class="version-row"><view class="version-copy"><text>版本 {{ targetVersion }}</text><text>{{ forceUpdate ? '需要更新后继续使用' : '更新后体验更稳定' }}</text></view><text class="version-badge" :class="{ required: forceUpdate }">{{ forceUpdate ? '必须更新' : '新版本' }}</text></view>
				<view class="notes-block"><text class="notes-heading">本次更新</text><scroll-view class="notes-scroll" scroll-y><text class="notes-content">{{ updateDescription }}</text></scroll-view></view>
				<view v-if="downloading" class="download-state"><view class="progress-track"><view class="progress-value" :style="{ width: progress + '%' }"></view></view><view class="progress-copy"><text>{{ statusMessage }}</text><text>{{ progress }}%</text></view></view>
				<view v-else class="update-actions"><view v-if="canCancel" class="action secondary" @tap="cancelUpdate">稍后更新</view><view class="action primary" @tap="confirmUpdate">{{ platformName === 'ios' ? '前往 App Store' : '立即更新' }}</view></view>
				<text class="security-line">更新由官方版本配置提供，数据仍保存在你的账号下</text>
			</view>
		</view>
	</view>
</template>
<script>
import { getAppUpdateConfig } from '@/api/index.js'
let checking = false
function parseConfig(value) { if (!value) return {}; if (typeof value === 'object') return value; try { return JSON.parse(value) } catch (error) { return {} } }
function getAppName() { return '哆米记账' }
function getRuntime() { const info = uni.getSystemInfoSync() || {}; let version = info.appVersion || '1.0.0'; let platform = String(info.osName || info.platform || '').toLowerCase(); /* #ifdef APP-PLUS */ version = plus.runtime.version || version; platform = String(plus.os.name || platform).toLowerCase(); /* #endif */ return { version, platform: platform.includes('ios') ? 'ios' : 'android' } }
async function loadUpdateConfig() { const appName = getAppName(); let primary = {}; let primaryError = null; try { primary = parseConfig(await getAppUpdateConfig(appName)) } catch (error) { primaryError = error } if (primary && Object.keys(primary).length) return primary; if (appName !== '哆米记账') { try { return parseConfig(await getAppUpdateConfig('哆米记账')) } catch (error) { if (primaryError) throw primaryError; throw error } } if (primaryError) throw primaryError; return primary }
export default {
 name: 'AppUpdate',
 data() { return { visible: false, downloading: false, progress: 0, statusMessage: '正在下载更新包', currentVersion: '1.0.0', targetVersion: '', updateDescription: '优化使用体验并修复已知问题。', platformName: 'android', updateConfig: { downloadUrl: '', updateType: 0, updateWay: 0 }, downloadTask: null } },
 computed: { forceUpdate() { return this.updateConfig.updateType === 2 }, canCancel() { return this.updateConfig.updateType === 1 || (this.platformName === 'ios' && !this.updateConfig.downloadUrl) } },
 methods: {
  async checkAppUpdate({ manual = false } = {}) {
   /* #ifndef APP-PLUS */ if (manual) uni.showToast({ title: '请在应用内检查更新', icon: 'none' }); return false /* #endif */
   /* #ifdef APP-PLUS */
   if (checking) return false; checking = true
   try { const runtime = getRuntime(); const payload = await loadUpdateConfig(); const config = runtime.platform === 'ios' ? { updateType: Number(payload.iosUpdateType || 0), updateWay: Number(payload.iosUpdateWay ?? 1), targetVersion: String(payload.iosAppVersion || ''), downloadUrl: String(payload.iosAppDownloadUrl || payload.iosDownloadUrl || payload.iosStoreUrl || payload.appStoreUrl || payload.h5DownloadUrl || ''), description: payload.iosVersionDesc || payload.versionDesc } : { updateType: Number(payload.androidUpdateType || 0), updateWay: Number(payload.androidUpdateWay || 0), targetVersion: String(payload.androidVersion || ''), downloadUrl: String(payload.androidAppDownloadUrl || payload.androidDownloadUrl || payload.h5DownloadUrl || ''), description: payload.androidVersionDesc || payload.versionDesc }; const hasNewVersion = config.updateType > 0 && config.targetVersion && config.targetVersion !== runtime.version && (config.downloadUrl || runtime.platform === 'ios'); if (!hasNewVersion) { if (manual) uni.showToast({ title: '当前已是最新版本', icon: 'success' }); return false } this.currentVersion = runtime.version; this.targetVersion = config.targetVersion; this.platformName = runtime.platform; this.updateDescription = String(config.description || '优化使用体验并修复已知问题。').trim(); this.updateConfig = config; this.visible = true; uni.hideTabBar(); return true } catch (error) { if (manual) uni.showToast({ title: error.message || '暂时无法检查更新', icon: 'none' }); return false } finally { checking = false } /* #endif */
  },
  handleOverlayTap() { if (!this.downloading) uni.showToast({ title: '请先完成版本更新', icon: 'none' }) },
  cancelUpdate() { if (!this.canCancel || this.downloading) return; this.visible = false; uni.showTabBar(); this.$emit('dismiss') },
  confirmUpdate() { /* #ifdef APP-PLUS */ if (!this.updateConfig.downloadUrl) return uni.showToast({ title: '更新地址暂未配置', icon: 'none' }); if (this.platformName === 'ios' || this.updateConfig.updateWay === 1) return plus.runtime.openURL(this.updateConfig.downloadUrl, () => uni.showToast({ title: '无法打开更新地址', icon: 'none' })); this.downloading = true; this.downloadTask = uni.downloadFile({ url: this.updateConfig.downloadUrl, success: this.installDownloadedPackage, fail: () => this.resetDownload('更新包下载失败') }); if (this.downloadTask && this.downloadTask.onProgressUpdate) this.downloadTask.onProgressUpdate(result => { this.progress = Math.min(100, Math.max(0, Math.floor(result.progress || 0))); if (this.progress >= 100) this.statusMessage = '下载完成，正在准备安装' }) /* #endif */ },
  installDownloadedPackage(result) { /* #ifdef APP-PLUS */ if (!result || result.statusCode !== 200) return this.resetDownload('更新包下载失败'); this.progress = 100; this.statusMessage = '正在安装新版本'; plus.runtime.install(result.tempFilePath, { force: false }, () => { this.downloading = false; uni.showModal({ title: '更新已安装', content: '重启应用即可使用新版本。', showCancel: false, confirmText: '立即重启', success: () => plus.runtime.restart() }) }, () => this.resetDownload('新版本安装失败')) /* #endif */ },
  resetDownload(message) { this.downloading = false; this.progress = 0; uni.showToast({ title: message, icon: 'none' }) }
 },
 onUnload() { if (this.downloadTask && this.downloadTask.abort) this.downloadTask.abort(); if (this.visible) uni.showTabBar() }
}
</script>
<style scoped>
.update-overlay{position:fixed;z-index:9999;inset:0;display:flex;align-items:center;justify-content:center;padding:42rpx 30rpx;background:rgba(13,40,57,.48);box-sizing:border-box}.update-dialog{width:100%;max-width:650rpx;overflow:hidden;border-radius:28rpx;background:#fffdf8;box-shadow:0 30rpx 90rpx rgba(13,40,57,.24)}.update-header{position:relative;padding:42rpx 38rpx 34rpx;background:linear-gradient(135deg,#f7f2e8,#e7f0e8)}.close-button{position:absolute;top:22rpx;right:26rpx;width:58rpx;height:58rpx;border-radius:50%;background:rgba(255,255,255,.75);color:#143a55;font-size:44rpx;line-height:51rpx;text-align:center}.app-mark{position:relative;width:112rpx;height:112rpx;border-radius:26rpx;background:rgba(255,255,255,.8);box-shadow:0 16rpx 34rpx rgba(20,58,85,.12)}.mark-dot{position:absolute;top:17rpx;left:38rpx;width:34rpx;height:34rpx;border-radius:10rpx;background:#143a55}.mark-panel{position:absolute;left:21rpx;right:21rpx;bottom:18rpx;height:48rpx;padding:20rpx 9rpx 7rpx;border-radius:11rpx;background:#143a55;box-sizing:border-box;display:flex;gap:5rpx}.mark-panel view{flex:1;border-radius:4rpx;background:#bfe0d2}.mark-panel view:nth-child(2n){background:#f0a48e}.update-kicker,.update-title,.update-subtitle{display:block}.update-kicker{margin-top:24rpx;color:#4a8b79;font-size:21rpx;font-weight:700}.update-title{margin-top:12rpx;color:#143a55;font-size:42rpx;font-weight:800}.update-subtitle{margin-top:10rpx;color:#7e8896;font-size:23rpx}.update-body{padding:28rpx 30rpx}.version-row{display:flex;align-items:center;justify-content:space-between;gap:18rpx;padding:20rpx;border:1rpx solid rgba(20,58,85,.08);border-radius:20rpx;background:#fff}.version-copy{flex:1;min-width:0}.version-copy text{display:block}.version-copy text:first-child{color:#1a2530;font-size:28rpx;font-weight:800}.version-copy text:last-child{margin-top:7rpx;color:#7e8896;font-size:21rpx}.version-badge{flex:0 0 auto;padding:9rpx 14rpx;border-radius:999rpx;background:#e4f0e9;color:#35745f;font-size:20rpx;font-weight:700}.version-badge.required{background:#fbe5df;color:#c65e4c}.notes-block{margin-top:24rpx;padding:20rpx;border-radius:20rpx;background:#f4f7f1}.notes-heading{display:block;color:#35745f;font-size:23rpx;font-weight:800}.notes-scroll{max-height:220rpx;margin-top:12rpx}.notes-content{display:block;color:#7e8896;font-size:23rpx;line-height:1.7;white-space:pre-wrap;word-break:break-word}.download-state{margin-top:26rpx}.progress-track{height:14rpx;overflow:hidden;border-radius:999rpx;background:#e2eee7}.progress-value{height:100%;border-radius:999rpx;background:#4a8b79;transition:width .25s}.progress-copy{display:flex;justify-content:space-between;margin-top:11rpx;color:#7e8896;font-size:21rpx}.update-actions{display:flex;gap:14rpx;margin-top:26rpx}.action{flex:1;height:82rpx;border-radius:999rpx;font-size:25rpx;font-weight:800;line-height:82rpx;text-align:center}.secondary{border:1rpx solid rgba(20,58,85,.12);color:#7e8896}.primary{background:#143a55;color:#fffdf8}.security-line{display:block;margin-top:20rpx;color:#a0a8af;font-size:19rpx;line-height:1.4;text-align:center}
</style>
